/// <summary>
/// CoC extension method.
/// </summary>
/// <param name = "_custAccountStatementExtTmp">The instance of <c>CustAccountStatementExtTmp</c> to coppy data from. </param>
/// <param name = "_statementRecId">The statement to filter the copying of data.</param>    
protected void insertNewRecords(CustAccountStatementExtTmp _custAccountStatementExtTmp, RecId _statementRecId)
{
    next insertNewRecords(_custAccountStatementExtTmp, _statementRecID);
    
    // MPJ_13531
    ttsbegin;
    Map custImage = new Map(Types::String, Types::Container);   // <CustAccount, ImageData>
    while select forupdate _custAccountStatementExtTmp
    {
        container imgData;
        if(custImage.exists(_custAccountStatementExtTmp.AccountNum))
        {
            imgData = custImage.lookup(_custAccountStatementExtTmp.AccountNum);
        }
        else
        {
            Image img = CustTable::metGetCustReportLogo(custAccountStatementExtTmpNew.AccountNum);
            if(img != null)
            {
                imgData = img.getData();
            }
            custImage.insert(_custAccountStatementExtTmp.AccountNum, imgData);
        }
        if(conLen(imgData) > 0)
        {
            _custAccountStatementExtTmp.CompanyLogo = imgData;
            _custAccountStatementExtTmp.update();
        }
    }
    ttscommit;
}
